import Component from 'flarum/common/Component';
/**
 * Renders a 0–5 star rating with full / half / empty stars (Font Awesome),
 * matching the MyBB Community Reviews display.
 */
export default class StarRating extends Component {
  view() {
    const max = this.attrs.max || 5;
    const rating = Math.max(0, Math.min(max, Number(this.attrs.rating) || 0));
    const stars = [];
    for (let i = 1; i <= max; i++) {
      let cls;
      if (rating >= i) {
        cls = 'fas fa-star';
      } else if (rating >= i - 0.5) {
        cls = 'fas fa-star-half-alt';
      } else {
        cls = 'far fa-star';
      }
      stars.push(m("i", {
        className: "".concat(cls, " StarRating-star"),
        key: i
      }));
    }
    return m("span", {
      className: "StarRating",
      title: "".concat(rating.toFixed(2), " / ").concat(max)
    }, stars);
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'forum/reviews/StarRating', StarRating);