import _defineProperty from "@babel/runtime/helpers/esm/defineProperty";
import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Link from 'flarum/common/components/Link';
import humanTime from 'flarum/common/helpers/humanTime';
import StarRating from './StarRating';

/**
 * Aba "Reviews" do perfil: lista os reviews de produto escritos pelo usuário
 * (espelha a aba User reviews do MyBB).
 */
export default class UserReviewsPage extends UserPage {
  constructor() {
    super(...arguments);
    _defineProperty(this, "reviews", []);
    _defineProperty(this, "loading", true);
  }
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    app.store.find('tfb-product-reviews', {
      forUser: user.id(),
      page: {
        limit: 50
      }
    }).then(res => {
      this.reviews = Array.from(res);
      this.loading = false;
      m.redraw();
    }).catch(() => {
      this.loading = false;
      m.redraw();
    });
  }
  content() {
    if (this.loading) {
      return m("div", {
        className: "UserReviews"
      }, m(LoadingIndicator, null));
    }
    if (this.reviews.length === 0) {
      return m("div", {
        className: "UserReviews"
      }, m("p", {
        className: "muted"
      }, app.translator.trans('huseyinfiliz-traderfeedback.forum.reviews.user_no_reviews')));
    }
    return m("div", {
      className: "UserReviews"
    }, this.reviews.map(r => {
      const product = r.product();
      return m("div", {
        className: "UserReviewRow",
        key: r.id()
      }, m("div", {
        className: "UserReviewRow-head"
      }, product ? m(Link, {
        href: app.route('reviews.product', {
          id: product.id()
        }),
        className: "UserReviewRow-product"
      }, product.name()) : m("span", {
        className: "UserReviewRow-product"
      }, "\u2014"), m(StarRating, {
        rating: r.rating()
      }), m("span", {
        className: "UserReviewRow-date"
      }, humanTime(r.createdAt()))), m("div", {
        className: "UserReviewRow-comment"
      }, r.comment()));
    }));
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'forum/reviews/UserReviewsPage', UserReviewsPage);