import Component from 'flarum/common/Component';
/**
 * Seletor de nota 1–max por estrelas clicáveis (usado no formulário de review).
 */
export default class StarInput extends Component {
  view() {
    const max = this.attrs.max || 5;
    const value = Number(this.attrs.value) || 0;
    const stars = [];
    for (let i = 1; i <= max; i++) {
      stars.push(m("i", {
        className: (i <= value ? 'fas' : 'far') + ' fa-star StarInput-star',
        key: i,
        onclick: () => this.attrs.onchange(i),
        role: "button",
        "aria-label": "".concat(i)
      }));
    }
    return m("span", {
      className: "StarInput"
    }, stars);
  }
}
flarum.reg.add('huseyinfiliz-traderfeedback', 'forum/reviews/StarInput', StarInput);